// DiffusionCharacterNode.swift
// CharacterNode backed by per-JumpPhase SKTextures generated by on-device Stable Diffusion.
// Falls back to single-texture tilt behaviour (like GeneratedCharacterNode) while textures
// are being generated, then swaps to per-phase textures once they arrive.

import SpriteKit
import UIKit

final class DiffusionCharacterNode: SKNode, CharacterNode {

    private static let displayHeight: CGFloat = 52

    // Set after all 6 poses finish generating.
    private(set) var phaseTextures: [JumpPhase: SKTexture] = [:]

    private let sprite: SKSpriteNode
    private var spinnerNode: SKShapeNode?
    private var currentPhase: JumpPhase = .idle

    init(fallbackImage: UIImage) {
        let tex    = SKTexture(image: fallbackImage)
        let aspect = tex.size().width / max(tex.size().height, 1)
        let size   = CGSize(width: Self.displayHeight * aspect, height: Self.displayHeight)
        sprite = SKSpriteNode(texture: tex, size: size)
        sprite.anchorPoint = CGPoint(x: 0.5, y: 0)
        super.init()
        addChild(sprite)
        startLoadingAnimation()
    }

    required init?(coder: NSCoder) { fatalError("init(coder:) not supported") }

    // Called by DiffusionGeneratorView once all phases have been generated.
    func applyTextures(_ textures: [JumpPhase: SKTexture]) {
        phaseTextures = textures
        stopLoadingAnimation()
        setPhase(currentPhase, duration: 0)
    }

    // MARK: - CharacterNode

    func setPhase(_ phase: JumpPhase, duration: TimeInterval = 0.08) {
        currentPhase = phase
        if let texture = phaseTextures[phase] {
            sprite.run(.setTexture(texture, resize: false))
            sprite.run(.rotate(toAngle: 0, duration: duration, shortestUnitArc: true))
        } else {
            // Tilt the fallback image while generation is pending.
            let tilt: CGFloat
            switch phase {
            case .ascending:  tilt = -0.12
            case .descending: tilt =  0.10
            default:          tilt =  0.00
            }
            sprite.run(.rotate(toAngle: tilt, duration: duration, shortestUnitArc: true))
        }
    }

    // MARK: - Loading indicator

    private func startLoadingAnimation() {
        sprite.alpha = 0.5
        // Faint pulsing ring centred on the sprite's mid-point.
        let ring = SKShapeNode(circleOfRadius: 7)
        ring.strokeColor = .white
        ring.lineWidth   = 1.5
        ring.fillColor   = .clear
        ring.alpha       = 0.8
        ring.position    = CGPoint(x: 0, y: Self.displayHeight / 2)
        addChild(ring)
        ring.run(.repeatForever(.sequence([
            .fadeAlpha(to: 0.2, duration: 0.5),
            .fadeAlpha(to: 0.8, duration: 0.5),
        ])))
        spinnerNode = ring
    }

    private func stopLoadingAnimation() {
        spinnerNode?.removeFromParent()
        spinnerNode = nil
        sprite.alpha = 1
    }
}
